	{
		[Test]
		public void TestSuccess()
		{
			var adapter = CreateAdapter(TestClientID, TestClientPassword);

			using (var stream = new MemoryStream(Encoding.ASCII.GetBytes(SampleMessage)))
			{
				var message = new eHubMessage(Guid.NewGuid(), TestClientID, JPCustomsID, MessageSchemaType.Xml, "UDM", "http://www.cargowise.com/Schemas/Universal", stream);
				adapter.Outbox.AddMessage(message);
				adapter.SendMessages();

				var expectedInboxMessageContent = stream.CompressAndEncode().ReadToEnd();

				var requesterIPAddress = GetIP4Address(GatewayHttpsUri.Host == "localhost" ? "localhost" : Dns.GetHostName());
				var expectedFileNameOverridePossible1 = requesterIPAddress + ";" + GetGatewayServerIP4Address();
				var expectedFileNameOverridePossible2 = "<UNKNOWN>" + ";" + GetGatewayServerIP4Address();

				Assert.IsTrue(
					FindInboxMessage(message.TrackingID, TestClientPK, "UDM", JPCustomsPK, "http://www.cargowise.com/Schemas/Universal", "", expectedFileNameOverridePossible1, expectedInboxMessageContent, 0, 0)
					|| FindInboxMessage(message.TrackingID, TestClientPK, "UDM", JPCustomsPK, "http://www.cargowise.com/Schemas/Universal", "", expectedFileNameOverridePossible2, expectedInboxMessageContent, 0, 0)
				);
			}
		}

